// v0.61.165 — /ver Periodical owner sub-menu. PR 2 of 3 in the
// reference-count admin lever. Browses the 14 items the v0.61.164
// data layer tracks, lets the operator Re-check (run the recount
// fn), Revert (display-only switch to a prior count), or Clear
// the history. Inline keyboards only — no TMA changes.
//
// Callback grammar:
//   per:menu                — open the top-level item list
//   per:item:<id>           — open a single item's panel (current
//                              + last 12 history + action buttons)
//   per:recheck:<id>        — run recountOne for the item; show
//                              the new entry + return to panel
//   per:revert:<id>:<ts>    — revertTo(<ts>); return to panel
//   per:clear:<id>          — clearHistory; return to panel
//   per:close               — dismiss the panel (delete message)

// Item label + emoji used in the inline-keyboard buttons + headers.
// Kept here (not in count-history) because labels are UI concern.
const PER_ITEM_LABEL = Object.freeze({
  'cuisines':           '🍽 Cuisines',
  'michelin':           '✳️ Michelin',
  'hawker':             '🥘 Hawker',
  'healthier-eateries': '🥗 Healthier Choice',
  'buildings':          '🏢 Buildings',
  'bus-stops':          '🚌 Bus stops',
  'train-stations':     '🚉 Train stations',
  'train-lines':        '🚊 Train lines',
  'carparks':           '🅿️ Carparks',
  'parks':              '🌳 Parks',
  'attractions':        '⚝ Attractions',
  'clinics':            '💊 Clinics',
  'hospitals':          '🏥 Hospitals',
  'police':             '👮 Police'
});

async function ownerPeriodicalMenu(chatId, messageId = null) {
  const { ITEMS } = require('./count-history');
  const cadenceMod = require('./count-cadence');
  // v0.61.175 — operator: each button now shows the current
  // CADENCE in parens (off / M / 4M / Yr), not the count. The
  // count surfaces inside the per-item panel along with history.
  // Two quick-action buttons added below: "▶️ Run now" (same call
  // as the prior "🔄 Re-check all" — recountAll) + "🔇 Set all
  // off" — one-tap kill switch that flips every cadence to 'off'.
  const cadShort = (v) => v === '4-monthly' ? '4M' : v === 'yearly' ? 'Yr' : v === 'manual' ? 'M' : 'off';
  const cadences = await cadenceMod.listAll(redis, ITEMS);
  const rows = [];
  for (let i = 0; i < ITEMS.length; i += 2) {
    const r = [];
    for (let j = i; j < Math.min(i + 2, ITEMS.length); j++) {
      const item = ITEMS[j];
      const label = PER_ITEM_LABEL[item] || item;
      const cad = cadShort(cadences.get(item) || 'manual');
      r.push({ text: `${label} (${cad})`, callback_data: `per:item:${item}` });
    }
    rows.push(r);
  }
  rows.push([
    { text: '▶️ Run now', callback_data: 'per:recheck-all' },
    { text: '🔇 Set all off', callback_data: 'per:set-all-off' }
  ]);
  rows.push([{ text: '✕ Close', callback_data: 'per:close' }]);
  // v0.61.176 — operator: surface the running version inline so a
  // glance at the menu confirms which build is live (the prior pain
  // point was a silent Railway redeploy delay between merge + live).
  const text = `📊 <b>Periodical — cadence per item</b>  ·  <i>v${pkgJson.version}</i>\nButton shows cadence (off / M / 4M / Yr). Tap an item to see count + history + change cadence.`;
  const payload = { parse_mode: 'HTML', reply_markup: { inline_keyboard: rows } };
  if (messageId) {
    try { await bot.editMessageText(text, { chat_id: chatId, message_id: messageId, ...payload }); return; }
    catch { /* fall through to fresh send */ }
  }
  await bot.sendMessage(chatId, text, payload);
}

async function ownerPeriodicalItemPanel(chatId, messageId, item) {
  const ch = require('./count-history');
  if (!ch.isKnownItem(item)) {
    await safeSend(chatId, `Unknown item: ${item}`);
    return;
  }
  const label = PER_ITEM_LABEL[item] || item;
  const history = await ch.getHistory(redis, item);
  // v0.61.166 — show the current cadence in the panel header. The
  // 4 cadence values are toggleable from the row below.
  const cadenceMod = require('./count-cadence');
  const currentCadence = await cadenceMod.getCadence(redis, item);
  const lines = [`📊 <b>${label}</b> · cadence: <i>${currentCadence}</i>`];
  if (!history.length) {
    lines.push('', '<i>No history yet — tap 🔄 Re-check to seed the first entry.</i>');
  } else {
    lines.push(`<b>Current:</b> ${history[0].n} <i>(${history[0].source})</i>`);
    if (history.length > 1) {
      lines.push('', '<b>History</b> (newest → oldest):');
      for (const e of history) {
        const d = new Date(e.ts);
        const dateStr = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
        lines.push(`  • ${e.n} <i>(${e.source}, ${dateStr})</i>`);
      }
    }
  }
  // Action buttons.
  const rows = [];
  rows.push([{ text: '🔄 Re-check now', callback_data: `per:recheck:${item}` }]);
  // v0.61.166 — cadence picker. 4 inline buttons; the active one
  // gets a ✓ prefix. Tapping calls per:set-cadence:<item>:<value>.
  const cadenceLabel = (v) => `${currentCadence === v ? '✓ ' : ''}${v === '4-monthly' ? '4M' : v === 'yearly' ? '1Y' : v === 'manual' ? 'M' : 'Off'}`;
  rows.push([
    { text: `⏰ ${cadenceLabel('manual')}`,    callback_data: `per:set-cadence:${item}:manual` },
    { text: `⏰ ${cadenceLabel('4-monthly')}`, callback_data: `per:set-cadence:${item}:4-monthly` },
    { text: `⏰ ${cadenceLabel('yearly')}`,    callback_data: `per:set-cadence:${item}:yearly` },
    { text: `⏰ ${cadenceLabel('off')}`,       callback_data: `per:set-cadence:${item}:off` }
  ]);
  // Revert is a sub-row showing up to 4 most recent historical
  // entries (excluding the current = history[0]); each button
  // carries the ts so the callback can dispatch directly.
  if (history.length >= 2) {
    const revertRow = [];
    for (let i = 1; i < Math.min(history.length, 5); i++) {
      const e = history[i];
      revertRow.push({ text: `⏪ ${e.n}`, callback_data: `per:revert:${item}:${e.ts}` });
    }
    rows.push(revertRow);
  }
  if (history.length) {
    rows.push([{ text: '🗑 Clear history', callback_data: `per:clear:${item}` }]);
  }
  rows.push([{ text: '◀ Back', callback_data: 'per:menu' },
             { text: '✕ Close', callback_data: 'per:close' }]);
  const payload = { parse_mode: 'HTML', reply_markup: { inline_keyboard: rows } };
  try {
    await bot.editMessageText(lines.join('\n'), { chat_id: chatId, message_id: messageId, ...payload });
  } catch {
    await bot.sendMessage(chatId, lines.join('\n'), payload);
  }
}

