// v0.61.177 — fires the 48-cuisine Places sweep server-side using
// the prod GOOGLE_MAPS_API_KEY env var. Acknowledges immediately,
// runs countAll (~15 s, parallel), persists the result to Redis,
// then sends a final summary message + re-opens the menu so the
// operator sees the updated state without re-tapping.
async function ownerCuisineVenueRecount(chatId) {
  const cvc = require('./cuisine-venue-counts');
  if (!process.env.GOOGLE_MAPS_API_KEY) {
    await safeSend(chatId, '⚠️ GOOGLE_MAPS_API_KEY not set on the server — cannot run sweep.');
    return;
  }
  // v0.61.179 — 60-second debounce so a double-tap doesn't spend
  // ~\$7 instead of ~\$3.50. Friendly "wait N seconds" reply if
  // the slot is held by a recent caller.
  const slot = await cvc.claimDebounceSlot(redis);
  if (!slot.won) {
    await safeSend(chatId, `⏱ Another sweep just ran — wait ${slot.remainingSec} s before re-running (debounce prevents accidental double-charge).`);
    return;
  }
  await safeSend(chatId, `⏳ Running Places sweep across ${cvc.SCOPE_SLUGS.length} cuisines… (~15 s)`);
  let result;
  try {
    result = await cvc.countAll();
  } catch (err) {
    await safeSend(chatId, `❌ Sweep failed: ${String(err && err.message || err).slice(0, 200)}`);
    return;
  }
  const persisted = await cvc.persistToRedis(redis, result);
  const cappedN = Array.isArray(result.capped) ? result.capped.length : 0;
  const errN = result.errors ? Object.keys(result.errors).length : 0;
  const summary = [
    `✅ <b>Sweep complete.</b>`,
    `<b>Total:</b> ${result.total} venues across ${cvc.SCOPE_SLUGS.length} cuisines.`,
    `<b>Capped (60+):</b> ${cappedN}  ·  <b>Errors:</b> ${errN}  ·  <b>Pages:</b> ${result.pages}  ·  <b>Elapsed:</b> ${(result.elapsedMs / 1000).toFixed(1)} s.`,
    persisted ? `<i>Stored in Redis (key: cuisine-venue-counts:latest, TTL 60d).</i>` : `<i>⚠️ Redis persist failed — result NOT stored.</i>`
  ].join('\n');
  await bot.sendMessage(chatId, summary, { parse_mode: 'HTML' }).catch(() => {});
  // Re-open the menu so operator sees the refreshed view.
  await ownerCuisineVenueMenu(chatId, null);
}

// v0.61.183 — per-cuisine detail dump for the chat cv: menu.
// Loads the latest sweep result + renders a sorted-by-count table
// of all 48 slugs in a Markdown code block. Chunks the output if
// it exceeds Telegram's 4096-char per-message limit (shouldn't at
// 48 rows but defensive).
async function ownerCuisineVenueDetails(chatId) {
  const cvc = require('./cuisine-venue-counts');
  const latest = await cvc.loadFromRedis(redis);
  if (!latest || !latest.perSlug) {
    await safeSend(chatId, 'ℹ️ No cuisine-venue sweep data yet. Tap 🔄 Run now first.');
    return;
  }
  const entries = Object.entries(latest.perSlug);
  // Sort: errors (null) last, then by count desc, then alpha.
  entries.sort((a, b) => {
    const an = a[1], bn = b[1];
    if (an == null && bn == null) return a[0].localeCompare(b[0]);
    if (an == null) return 1;
    if (bn == null) return -1;
    if (an !== bn) return bn - an;
    return a[0].localeCompare(b[0]);
  });
  const capped = new Set(Array.isArray(latest.capped) ? latest.capped : []);
  const tiled = new Set(Array.isArray(latest.tiledSlugs) ? latest.tiledSlugs : []);
  // Build rows: "slug ........ n [60+|tiled|err]"
  const slugMax = Math.max(...entries.map(([s]) => s.length));
  const rows = entries.map(([slug, n]) => {
    const flag = n == null
      ? ' err'
      : capped.has(slug)
        ? ' 60+'
        : tiled.has(slug)
          ? ' (tiled)'
          : '';
    const nStr = n == null ? '—' : String(n);
    return `  ${slug.padEnd(slugMax + 2, '.')}${nStr.padStart(5)}${flag}`;
  });
  const header = `Cuisine venue counts (${cvc.SCOPE_SLUGS.length} cuisines) — total: ${latest.total ?? '?'}`;
  // Chunk into ≤3500-char blocks (leaving headroom for code-block markdown).
  const CHUNK = 3500;
  let block = header + '\n';
  const blocks = [];
  for (const row of rows) {
    if (block.length + row.length + 1 > CHUNK) {
      blocks.push(block);
      block = '';
    }
    block += row + '\n';
  }
  if (block) blocks.push(block);
  for (const b of blocks) {
    await bot.sendMessage(chatId, '```\n' + b + '```', { parse_mode: 'Markdown' }).catch(() => {});
  }
}

// v0.61.213 — Place-Search Variance test menu, owner-gated.
